<script setup lang="ts">
import { reviewTerm, readableChineseText, transcriptSourceLabel, proofreadingModelName, lessonAsrModelName } from '@/utils/reviewPresentation'
import { computed, nextTick, ref, watch } from 'vue'
import { useLessonReviewStore } from '@/stores/lessonReview'
import { formatReviewTime } from '@/utils/lessonReview'
import LessonCorrectionComparison from './LessonCorrectionComparison.vue'
import LessonModelUpgrade from './LessonModelUpgrade.vue'
const store = useLessonReviewStore()
const tab = ref<'transcript' | 'slides'>('transcript')
const search = ref('')
const compareRaw = ref(false)
const imageError = ref(false)
const follow = ref(true)
const list = ref<HTMLElement | null>(null)
const visibleTranscript = computed(() => store.displayTranscripts.filter(t => !search.value || t.text.includes(search.value) || (compareRaw.value && t.original_text.includes(search.value))))
watch(() => store.data?.lesson.id, () => { tab.value = store.data?.transcript.length ? 'transcript' : 'slides' }, { immediate: true })
watch(() => store.currentSlide?.image_url, () => { imageError.value = false })
watch(() => store.transcripts[0]?.id, async () => { if (follow.value && !search.value && tab.value === 'transcript') { await nextTick(); const active = list.value?.querySelector<HTMLElement>('[aria-current="true"]'); if (active && list.value) list.value.scrollTop = active.offsetTop - list.value.offsetTop - list.value.clientHeight / 3 } })
</script>
<template>
  <section id="evidence" class="panel lesson-evidence">
    <div class="panel-heading"><div><h2>语音与课件</h2><p>保留原生时间与识别来源，逐段回到课堂</p></div><span class="tag">{{ store.timeText }}</span></div>
    <p v-if="store.data?.lesson.modalities.audio === 'unrecognized'" class="evidence-footnote">本片段未识别到可靠语音；以下展示实际画面文字，未补写教师台词。</p>
    <div class="slide-preview"><img v-if="store.currentSlide?.image_url && !imageError" :src="store.currentSlide.image_url" :alt="readableChineseText(store.currentSlide.title) || '当前观测课件画面'" @error="imageError = true" /><div v-else class="empty-state">{{ imageError ? '当前课件图片无法访问，仍可查看提取文本。' : '此刻没有已对齐的课件画面。' }}</div><div v-if="store.currentSlide" class="slide-preview-caption"><strong>{{ readableChineseText(store.currentSlide.title) || '课堂画面文字待核验' }}</strong><span>{{ formatReviewTime(store.currentSlide.start_sec) }}–{{ formatReviewTime(store.currentSlide.end_sec) }}</span><small>{{ reviewTerm(store.currentSlide.method) }} · 边界不确定度 {{ store.currentSlide.uncertainty_sec }} 秒</small></div></div>
    <div class="evidence-tabs" role="tablist" aria-label="课堂证据类型"><button role="tab" :aria-selected="tab === 'transcript'" :class="{ active: tab === 'transcript' }" @click="tab = 'transcript'">语音段落 <span>{{ store.data?.transcript.length }}</span></button><button role="tab" :aria-selected="tab === 'slides'" :class="{ active: tab === 'slides' }" @click="tab = 'slides'">课件页段 <span>{{ store.observedSlides.length }}</span></button></div>
    <template v-if="tab === 'transcript'">
      <p v-if="store.data" class="evidence-footnote" data-testid="active-asr-model">语音识别：{{ lessonAsrModelName(store.data.lesson.provenance) }} · 机器识别待核验</p>
      <div v-if="store.data?.teacher_transcript" class="proofread-mode" data-testid="transcript-teacher-default"><span>教师核对稿优先显示<small>逐段显示核验状态。未修改的机器上下文仍需回听核验。</small></span><button data-testid="transcript-raw-toggle" :aria-pressed="compareRaw" @click="compareRaw = !compareRaw">{{ compareRaw ? '收起原始转写' : '对照原始转写' }}</button></div>
      <div v-else-if="store.data?.transcript_proofreading" class="proofread-mode" data-testid="transcript-proofread-default"><span>机器校对 · 待人工核验<small data-testid="active-correction-model">{{ proofreadingModelName(store.data.transcript_proofreading.model, store.data.transcript_proofreading.provenance) }}</small><small>结合本课原声与课件词汇修正，未确认内容保留原文。</small></span><button data-testid="transcript-raw-toggle" :aria-pressed="compareRaw" @click="compareRaw = !compareRaw">{{ compareRaw ? '收起原始转写' : '对照原始转写' }}</button></div>
      <div class="transcript-tools"><input v-model="search" type="search" aria-label="搜索课堂转写" placeholder="搜索课堂中的一句话…" /><label><input v-model="follow" type="checkbox" />跟随播放</label></div>
      <div ref="list" class="transcript-list" role="tabpanel"><button v-for="segment in visibleTranscript" :key="segment.id" :class="['transcript-item', { current: store.transcripts.some(t => t.id === segment.id) }]" :aria-current="store.transcripts.some(t => t.id === segment.id) ? 'true' : undefined" @click="store.seek(segment.start_sec)"><span class="segment-clock mono">{{ formatReviewTime(segment.start_sec) }}<small>{{ formatReviewTime(segment.end_sec) }}</small></span><div><p>{{ segment.text }}</p><div v-if="compareRaw && (segment.teacher || segment.proofreading)" class="raw-comparison" data-testid="transcript-raw-comparison"><span>原始转写</span><p>{{ segment.original_text }}</p><small v-if="segment.proofreading?.edits.length">校对 {{ segment.proofreading.edits.length }} 处 · {{ segment.proofreading.source_refs.join(' / ') }}</small><small v-if="segment.proofreading?.uncertainties.length">待核验：{{ segment.proofreading.uncertainties.join('；') }}</small></div><small>{{ segment.teacher ? `${segment.teacher.id} · ${segment.teacher.human_verified ? '教师已核对' : '机器上下文 · 未核验'}` : segment.proofreading ? `${segment.proofreading.id} · 机器校对 · 待核验` : `${segment.id} · ${transcriptSourceLabel(segment)}` }}</small></div></button><p v-if="!visibleTranscript.length" class="empty-state">{{ search ? '没有匹配的转写片段。' : '本课尚未提供语音转写。' }}</p></div><p class="evidence-footnote">机器转写与校对可能有误，请对照原声核验；原始转写、校对改动及来源完整保留在导出数据中。</p>
      <LessonCorrectionComparison />
      <LessonModelUpgrade />
    </template>
    <div v-else class="slide-list" role="tabpanel"><button v-for="slide in store.observedSlides" :key="slide.id" :class="['slide-item', { current: store.currentSlide?.id === slide.id }]" @click="store.seek(slide.start_sec)"><span>{{ formatReviewTime(slide.start_sec) }}–{{ formatReviewTime(slide.end_sec) }}</span><strong>{{ readableChineseText(slide.title) || '课堂画面文字待核验' }}</strong><p>{{ readableChineseText(slide.text) || '当前画面未提取到足够可读的中文，请查看原图。' }}</p><small>{{ slide.id }} · {{ reviewTerm(slide.method) }} · 边界不确定度 {{ slide.uncertainty_sec }} 秒</small></button><p v-if="!store.observedSlides.length" class="empty-state">尚无课件页段，不按课程时长推测页码或内容。</p></div>
  </section>
</template>
<style scoped>
