.slide-preview{margin:0 22px 20px;background:#e3edfa;border:1px solid #ccddf5;border-radius:8px;overflow:hidden}.slide-preview img{display:block;width:100%;max-height:360px;object-fit:contain;background:#d2e1f7}.slide-preview-caption{display:flex;align-items:center;flex-wrap:wrap;gap:8px 14px;padding:14px 16px}.slide-preview-caption strong{font-size:12px;font-weight:500;flex:1;color:#496284}.slide-preview-caption>span{font-size:10px;color:#5d7494}.slide-preview-caption small{width:100%;font-size:9px;color:#647da0}.evidence-tabs{display:flex;border-bottom:1px solid var(--line);padding:0 23px;gap:26px}.evidence-tabs button{font-size:12px;padding:10px 0 13px;background:none;color:#667d9e;border-bottom:2px solid transparent}.evidence-tabs button.active{color:var(--navy);border-color:var(--blue)}.evidence-tabs span{font-size:9px;margin-left:5px;color:#647da0}.transcript-tools{display:flex;gap:12px;align-items:center;padding:15px 22px}.transcript-tools>input{border:1px solid var(--line);border-radius:6px;padding:9px 10px;font-size:11px;background:#f4f8fd;min-width:0;flex:1;color:var(--ink)}.transcript-tools label{font-size:10px;color:#61799b;display:flex;align-items:center;gap:4px;white-space:nowrap}.transcript-tools input[type=checkbox]{accent-color:var(--blue)}.transcript-list{max-height:340px;overflow:auto;position:relative;margin:0 13px}.transcript-item{width:100%;display:flex;gap:17px;text-align:left;padding:13px 12px;border-radius:6px;background:none}.transcript-item:hover{background:#eaf1fb}.transcript-item.current{background:#e0eaf9}.segment-clock{font-size:10px;color:#55729a;display:block;padding-top:3px;flex-shrink:0;min-width:33px}.segment-clock small{display:block;margin-top:6px;font-size:9px;color:#5d7ca7}.transcript-item>div{min-width:0}.transcript-item p{font-size:12px;line-height:1.9;color:#526682}.transcript-item div>small{font-size:9px;color:#617da3;margin-top:6px;display:block}.evidence-footnote{padding:15px 24px 20px;font-size:9px;line-height:1.8;color:#647da1}.slide-list{max-height:400px;overflow:auto;padding:12px 15px 20px}.slide-item{display:block;width:100%;text-align:left;background:none;border-bottom:1px solid #dee9f9;border-radius:6px;padding:15px 12px}.slide-item:hover,.slide-item.current{background:#e2ecfa}.slide-item>span{font-size:9px;color:#5779a7}.slide-item strong{display:block;font-size:12px;font-weight:500;color:#4c6384;margin:7px 0}.slide-item p{white-space:pre-wrap;font-size:11px;color:#617899;line-height:1.8;max-height:120px;overflow:auto}.slide-item small{display:block;font-size:9px;color:#607ca4;margin-top:9px}@media(max-width:550px){.proofread-mode{margin:16px 15px 0;flex-wrap:wrap;gap:8px}.proofread-mode button{margin-left:auto}.slide-preview{margin:0 15px 18px}.transcript-tools{padding:15px}.transcript-item{gap:12px}.transcript-list{margin:0 9px}}
